/* the pot sections' values (val[6..]) for the knobs k; val[0..5] come from mks_pi_load.h (PRES) */
static inline void mks_mna_pot_values(const MksMnaKnobs* k, double* val)
{
    bn_preamp_ckt_pot_values(k->VOL, k->TREB, k->BASS, k->MID, k->MASTER, &val[6], MKS_MK81_US_POTS);   /* MK 81's laws */
    val[15] = 22e3 * (1.0 - k->PRES) + 1.0;                                    /* VR6 presence (power.py) */
    { const double* jv = k->LOWIN > 0.5 ? BN_PREAMP_CKT_JACK_LOW : BN_PREAMP_CKT_JACK_HIGH;
      for (int j = 0; j < BN_PREAMP_CKT_N_JACK; ++j) { val[16 + j] = jv[j]; } }
    {  /* MK81#4: the 4x12 load at Cabinet Feel k (power.py: Re 7.17, RP 34.3, f0 116.6, Q 6.52, LVC 0.000885; flat 8.0 ohm) */
        const double kc = !(k->CAB >= 0.0005) ? 0.0005 : (k->CAB > 1.0 ? 1.0 : k->CAB);
        const double rp = 34.3 * kc;
        val[20] = 8.0 + kc * (7.17 - 8.0);
        val[21] = rp;
        val[22] = 6.52 / (2.0 * 3.141592653589793 * 116.6 * rp);
        val[23] = 0.000885 * kc;
        val[24] = rp / (2.0 * 3.141592653589793 * 116.6 * 6.52);
        val[25] = 40.3 * kc;   /* MK81#159: the voice coil's loss scales with LVC */
    }
    val[26] = 150.932;   /* MK81#195: rchg (bn_psu.h); ERA moves nothing on this head */
    val[27] = 0.0001;   /* MK81#195: C23 */
}
